const programCode = $('GetProgramFromDesktop').first().json.programCode;
const sourceLines = $('GetProgramFromDesktop').first().json.sourceLines || 0;

// Optionaler Name aus Webhook-Body
const webhookBody = $('Webhook').first().json.body || $('Webhook').first().json || {};
const customName = webhookBody.name || webhookBody.title || '';

const lines = programCode.split('\n').map(l => l.trim());
const commentLines = lines.filter(l => l.startsWith('#')).map(l => l.replace(/^#\s*/, ''));
const codeLines = lines.filter(l => l && !l.startsWith('#'));

// ======= Titel =======
let title = customName || (commentLines.length > 0 ? commentLines[0] : 'FPC Programm');
if (title.length > 100) title = title.substring(0, 100) + '...';

// ======= Beschreibung =======
const description = commentLines.join('\n');

// ======= Befehle extrahieren =======
const VALID_CMDS = ['GET','GETNOT','DUP','NOT','AND','OR','XOR','MOV','CMOV','SET','CSET','CINC','CDEC','CMP','GT','LE'];
const usedCmds = [...new Set(
  codeLines
    .map(l => l.split(/\s+/)[0].toUpperCase())
    .filter(c => VALID_CMDS.includes(c))
)];
const commands = usedCmds.join(', ');

// ======= Ressourcen extrahieren =======
const resources = { inputs: new Set(), outputs: new Set(), memory: new Set(), timers: new Set(), counters: new Set() };
for (const line of codeLines) {
  const parts = line.toUpperCase().split(/\s+/);
  const cmd = parts[0];
  let subject = '';
  let addr = -1;

  if (['GET','GETNOT'].includes(cmd) && parts.length >= 3) {
    subject = parts[1]; addr = parseInt(parts[2]);
  } else if (['MOV','CMOV'].includes(cmd) && parts.length >= 3) {
    subject = parts[1]; addr = parseInt(parts[2]);
  } else if (['SET','CSET'].includes(cmd) && parts.length >= 3) {
    subject = parts[1]; addr = parseInt(parts[2]);
  } else if (['CINC','CDEC','CMP','GT','LE'].includes(cmd) && parts.length >= 3) {
    subject = parts[1]; addr = parseInt(parts[2]);
  }

  if (!isNaN(addr) && addr >= 0) {
    if (subject === 'I') resources.inputs.add(addr);
    if (subject === 'O') resources.outputs.add(addr);
    if (subject === 'M') resources.memory.add(addr);
    if (subject === 'T') resources.timers.add(addr);
    if (subject === 'C') resources.counters.add(addr);
  }
}

const inputList = [...resources.inputs].sort((a,b) => a-b).map(i => `I${i}`);
const outputList = [...resources.outputs].sort((a,b) => a-b).map(i => `O${i}`);
const memoryList = [...resources.memory].sort((a,b) => a-b).map(i => `M${i}`);
const timerList = [...resources.timers].sort((a,b) => a-b).map(i => `T${i}`);
const counterList = [...resources.counters].sort((a,b) => a-b).map(i => `C${i}`);
const allResources = [...inputList, ...outputList, ...memoryList, ...timerList, ...counterList].join(', ');

// ======= Kategorie automatisch erkennen =======
let category = 'Grundlagen';
if (timerList.length > 0 && counterList.length > 0) category = 'Kombinierte Muster';
else if (timerList.length > 0) category = 'Timer und Blinker';
else if (counterList.length > 0) category = 'Counter Operationen';
else if (usedCmds.includes('CMOV') && memoryList.length > 0) category = 'Toggle-Logik';
else if (codeLines.length > 10) category = 'Kombinierte Muster';

// ======= Level automatisch erkennen =======
let level = 'Einfach';
if (codeLines.length > 15 || (timerList.length > 0 && counterList.length > 0)) level = 'Komplex';
else if (codeLines.length > 6 || timerList.length > 0 || counterList.length > 0 || memoryList.length > 1) level = 'Mittel';

// ======= Tags generieren =======
const tagSet = new Set();
usedCmds.forEach(c => tagSet.add(c));
if (timerList.length > 0) tagSet.add('Timer');
if (counterList.length > 0) tagSet.add('Counter');
if (memoryList.length > 0) tagSet.add('Memory');
if (usedCmds.includes('AND')) tagSet.add('Logik');
if (usedCmds.includes('OR')) tagSet.add('Logik');
if (usedCmds.includes('XOR')) tagSet.add('Wechselschaltung');
if (usedCmds.includes('NOT')) tagSet.add('Invertierung');
if (usedCmds.includes('GETNOT') && usedCmds.includes('DUP') && usedCmds.includes('CSET')) tagSet.add('Timer-Init');
if (usedCmds.includes('CINC') || usedCmds.includes('CDEC')) tagSet.add('Zaehler');
if (usedCmds.includes('CMP') || usedCmds.includes('GT') || usedCmds.includes('LE')) tagSet.add('Vergleich');
const tags = [...tagSet].join(', ');

// ======= Stack-Simulation =======
const STACK_FX = {
  'GET': 1, 'GETNOT': 1, 'DUP': 1, 'NOT': 0,
  'AND': -1, 'OR': -1, 'XOR': -1,
  'MOV': -1, 'CMOV': -1, 'CSET': -1,
  'SET': 0, 'CINC': 0, 'CDEC': 0,
  'CMP': 1, 'GT': 1, 'LE': 1
};
let stackDepth = 0;
for (const line of codeLines) {
  const cmd = line.split(/\s+/)[0].toUpperCase();
  const fx = STACK_FX[cmd];
  if (fx !== undefined) stackDepth = Math.max(0, stackDepth + fx);
}
const stackValid = stackDepth === 0;

// ======= Programmabschnitte aus Kommentaren =======
const sections = [];
let currentSection = null;
for (const line of lines) {
  if (line.startsWith('#')) {
    currentSection = line.replace(/^#\s*/, '');
  } else if (line && currentSection) {
    sections.push(currentSection);
    currentSection = null;
  }
}
const programSections = [...new Set(sections)].join(', ');

// ======= Text fuer Embedding =======
let textForEmbedding = `${title}\n`;
if (description) textForEmbedding += `${description}\n`;
textForEmbedding += `\nKategorie: ${category}. Level: ${level}.\n`;
textForEmbedding += `Inputs: ${inputList.join(', ') || 'keine'}. Outputs: ${outputList.join(', ') || 'keine'}.\n`;
if (memoryList.length) textForEmbedding += `Memory: ${memoryList.join(', ')}.\n`;
if (timerList.length) textForEmbedding += `Timer: ${timerList.join(', ')}.\n`;
if (counterList.length) textForEmbedding += `Counter: ${counterList.join(', ')}.\n`;
textForEmbedding += `Befehle: ${commands}.\n`;
if (programSections) textForEmbedding += `Abschnitte: ${programSections}.\n`;
textForEmbedding += `\nCode:\n${programCode}\n`;
textForEmbedding += `\nStack-Analyse: ${stackValid ? 'Stack korrekt (depth=0)' : 'WARNUNG: Stack nicht leer (depth=' + stackDepth + ')'}\n`;

return [{
  json: {
    title,
    description,
    category,
    level,
    commands,
    tags,
    resources: allResources,
    inputs: inputList.join(', '),
    outputs: outputList.join(', '),
    memory: memoryList.join(', '),
    timers: timerList.join(', '),
    counters: counterList.join(', '),
    codeLineCount: codeLines.length,
    commentLineCount: commentLines.length,
    stackValid,
    programSections,
    textForEmbedding,
    programCode
  }
}];
